: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n///\r\n/// @alias margin()\r\n///\r\n@mixin m(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include margin(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-axis()\r\n///\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center {\r\n  @include margin($x: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-center()\r\n///\r\n@mixin mx-auto {\r\n  @include margin-center;\r\n}\r\n\r\n@mixin margin-middle {\r\n  @include margin($y: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-middle()\r\n///\r\n@mixin my-auto {\r\n  @include margin-middle;\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n///\r\n/// @alias margin-all()\r\n///\r\n@mixin margin-square($margin) {\r\n  @include margin-all($margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin-all(auto);\r\n}\r\n\r\n///\r\n/// @alias margin-auto()\r\n///\r\n@mixin m-auto {\r\n  @include margin-auto;\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin-all(0);\r\n}\r\n\r\n///\r\n/// @alias margin-none()\r\n///\r\n@mixin m-none {\r\n  @include margin-none;\r\n}\r\n\r\n///\r\n/// @alias m-none()\r\n///\r\n@mixin m-0 {\r\n  @include m-none;\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-xy()\r\n///\r\n@mixin margin-axis($vertical: null, $horizontal: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-x($x: null) {\r\n  @include margin($x: $x);\r\n}\r\n\r\n///\r\n/// @alias margin-x()\r\n///\r\n@mixin mx($x: null) {\r\n  @include margin-x($x: $x);\r\n}\r\n\r\n@mixin mx-none {\r\n  @include mx($x: 0);\r\n}\r\n\r\n///\r\n/// @alias mx-none()\r\n///\r\n@mixin mx-0 {\r\n  @include mx-none;\r\n}\r\n\r\n@mixin margin-y($y: null) {\r\n  @include margin($y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-y()\r\n///\r\n@mixin my($y: null) {\r\n  @include margin-y($y: $y);\r\n}\r\n\r\n@mixin my-none {\r\n  @include my($y: 0);\r\n}\r\n\r\n///\r\n/// @alias my-none()\r\n///\r\n@mixin my-0 {\r\n  @include my-none;\r\n}\r\n\r\n@mixin margin-top($top: null) {\r\n  @include margin($top: $top);\r\n}\r\n\r\n///\r\n/// @alias margin-top()\r\n///\r\n@mixin mt($top: null) {\r\n  @include margin-top($top);\r\n}\r\n\r\n@mixin mt-none {\r\n  @include mt(0);\r\n}\r\n\r\n///\r\n/// @alias mt-none()\r\n///\r\n@mixin mt-0 {\r\n  @include mt-none;\r\n}\r\n\r\n@mixin margin-right($right: null) {\r\n  @include margin($right: $right);\r\n}\r\n\r\n///\r\n/// @alias margin-right()\r\n///\r\n@mixin mr($right: null) {\r\n  @include margin-right($right);\r\n}\r\n\r\n@mixin mr-none {\r\n  @include mr($right: 0);\r\n}\r\n\r\n///\r\n/// @alias mr-none()\r\n///\r\n@mixin mr-0 {\r\n  @include mr-none;\r\n}\r\n\r\n@mixin margin-bottom($bottom: null) {\r\n  @include margin($bottom: $bottom);\r\n}\r\n\r\n///\r\n/// @alias margin-bottom()\r\n///\r\n@mixin mb($bottom: null) {\r\n  @include margin-bottom($bottom: $bottom);\r\n}\r\n\r\n@mixin mb-none {\r\n  @include mb($bottom: 0);\r\n}\r\n\r\n///\r\n/// @alias mb-none()\r\n///\r\n@mixin mb-0 {\r\n  @include mb-none;\r\n}\r\n\r\n@mixin margin-left($left: null) {\r\n  @include margin($left: $left);\r\n}\r\n\r\n///\r\n/// @alias margin-left()\r\n///\r\n@mixin ml($left: null) {\r\n  @include margin-left($left: $left);\r\n}\r\n\r\n@mixin ml-none {\r\n  @include ml($left: 0);\r\n}\r\n\r\n///\r\n/// @alias ml-none()\r\n///\r\n@mixin ml-0 {\r\n  @include ml-none;\r\n}\r\n\r\n// padding\r\n\r\n@mixin padding(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: padding,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n///\r\n/// @alias padding()\r\n///\r\n@mixin p(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include padding(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin padding-xy($x: null, $y: null) {\r\n  @include padding($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias padding-xy()\r\n///\r\n@mixin padding-axis($horizontal: null, $vertical: null) {\r\n  @include padding-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin padding-all($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n///\r\n/// @alias padding-all()\r\n///\r\n@mixin padding-square($padding) {\r\n  @include padding-all($padding);\r\n}\r\n\r\n@mixin padding-none {\r\n  @include padding-all(0);\r\n}\r\n\r\n///\r\n/// @alias padding-none()\r\n///\r\n@mixin p-none {\r\n  @include padding-none;\r\n}\r\n\r\n///\r\n/// @alias p-none()\r\n///\r\n@mixin p-0 {\r\n  @include p-none;\r\n}\r\n\r\n@mixin padding-x($x: null) {\r\n  @include padding($x: $x);\r\n}\r\n\r\n///\r\n/// @alias padding-x()\r\n///\r\n@mixin px($x: null) {\r\n  @include padding-x($x);\r\n}\r\n\r\n@mixin px-none {\r\n  @include px(0);\r\n}\r\n\r\n///\r\n/// @alias px-none()\r\n///\r\n@mixin px-0 {\r\n  @include px-none;\r\n}\r\n\r\n@mixin padding-y($y: null) {\r\n  @include padding($y: $y);\r\n}\r\n\r\n///\r\n/// @alias padding-y()\r\n///\r\n@mixin py($y: null) {\r\n  @include padding-y($y);\r\n}\r\n\r\n@mixin py-none {\r\n  @include py(0);\r\n}\r\n\r\n///\r\n/// @alias py-none()\r\n///\r\n@mixin py-0 {\r\n  @include py-none;\r\n}\r\n\r\n@mixin padding-top($top: null) {\r\n  @include padding($top: $top);\r\n}\r\n\r\n///\r\n/// @alias padding-top()\r\n///\r\n@mixin pt($top: null) {\r\n  @include padding-top($top);\r\n}\r\n\r\n@mixin pt-none {\r\n  @include pt(0);\r\n}\r\n\r\n///\r\n/// @alias padding-top()\r\n///\r\n@mixin pt-0 {\r\n  @include pt-none;\r\n}\r\n\r\n@mixin padding-right($right: null) {\r\n  @include padding($right: $right);\r\n}\r\n\r\n///\r\n/// @alias padding-right()\r\n///\r\n@mixin pr($right: null) {\r\n  @include padding-right($right);\r\n}\r\n\r\n@mixin pr-none {\r\n  @include pr(0);\r\n}\r\n\r\n///\r\n/// @alias pr-none()\r\n///\r\n@mixin pr-0 {\r\n  @include pr-none;\r\n}\r\n\r\n@mixin padding-bottom($bottom: null) {\r\n  @include padding($bottom: $bottom);\r\n}\r\n\r\n///\r\n/// @alias padding-bottom()\r\n///\r\n@mixin pb($bottom: null) {\r\n  @include padding-bottom($bottom);\r\n}\r\n\r\n@mixin pb-none {\r\n  @include pb(0);\r\n}\r\n\r\n///\r\n/// @alias pb-none()\r\n///\r\n@mixin pb-0 {\r\n  @include pb-none;\r\n}\r\n\r\n@mixin padding-left($left: null) {\r\n  @include padding($left: $left);\r\n}\r\n\r\n///\r\n/// @alias padding-left()\r\n///\r\n@mixin pl($left: null) {\r\n  @include padding-left($left);\r\n}\r\n\r\n@mixin pl-none {\r\n  @include pl(0);\r\n}\r\n\r\n///\r\n/// @alias pl-none()\r\n///\r\n@mixin pl-0 {\r\n  @include pl-none;\r\n}\r\n","///\r\n/// @group flex\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n/// @since 0.1.0\r\n///\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -flex(\r\n  $direction: null,\r\n  $justify: null,\r\n  $align: null,\r\n  $inline: false,\r\n) {\r\n  display: if($inline, inline-flex, flex);\r\n\r\n  @if $direction and $direction != row {\r\n    flex-direction: $direction;\r\n  }\r\n\r\n  @if $justify and $justify != flex-