ft, if($l, $l, if($x, $x, if($a, $a, $all)))),\r\n  );\r\n}\r\n\r\n@mixin inset-all($all) {\r\n  @include inset($all: $all);\r\n}\r\n\r\n@mixin inset-none {\r\n  @include inset-all(0);\r\n}\r\n\r\n///\r\n/// @alias inset-none()\r\n///\r\n@mixin inset-0 {\r\n  @include inset-none;\r\n}\r\n\r\n@mixin inset-xy($x: null, $y: null) {\r\n  @include inset($x: $x, $y: $y);\r\n}\r\n\r\n@mixin inset-x($x) {\r\n  @include inset-xy($x: $x);\r\n}\r\n\r\n@mixin inset-x-none {\r\n  @include inset-x(0);\r\n}\r\n\r\n///\r\n/// @alias inset-x-none()\r\n///\r\n@mixin inset-x-0 {\r\n  @include inset-x-none;\r\n}\r\n\r\n@mixin inset-y($y) {\r\n  @include inset-xy($y: $y);\r\n}\r\n\r\n@mixin inset-y-none {\r\n  @include inset-y(0);\r\n}\r\n\r\n///\r\n/// @alias inset-y-none()\r\n///\r\n@mixin inset-y-0 {\r\n  @include inset-y-none;\r\n}\r\n\r\n@mixin top($top) {\r\n  @include inset($top: $top);\r\n}\r\n\r\n@mixin top-none {\r\n  @include top(0);\r\n}\r\n\r\n///\r\n/// @alias top-none()\r\n///\r\n@mixin top-0 {\r\n  @include top-none;\r\n}\r\n\r\n@mixin right($right) {\r\n  @include inset($right: $right);\r\n}\r\n\r\n@mixin right-none {\r\n  @include right(0);\r\n}\r\n\r\n///\r\n/// @alias right-none()\r\n///\r\n@mixin right-0 {\r\n  @include right-none;\r\n}\r\n\r\n@mixin bottom($bottom) {\r\n  @include inset($bottom: $bottom);\r\n}\r\n\r\n@mixin bottom-none {\r\n  @include bottom(0);\r\n}\r\n\r\n///\r\n/// @alias bottom-none()\r\n///\r\n@mixin bottom-0 {\r\n  @include bottom-none;\r\n}\r\n\r\n@mixin left($left) {\r\n  @include inset($left: $left);\r\n}\r\n\r\n@mixin left-none {\r\n  @include left(0);\r\n}\r\n\r\n///\r\n/// @alias left-none()\r\n///\r\n@mixin left-0 {\r\n  @include left-none;\r\n}\r\n\r\n@mixin unset-all {\r\n  @include inset-all(unset);\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($