 &.placementTop {\r\n    bottom: 100%;\r\n  }\r\n\r\n  &.placementBottom {\r\n    top: 100%;\r\n  }\r\n}\r\n\r\n// SelectMenuList\r\n\r\n.menuList {\r\n  position: relative;\r\n  // overflow-y: auto;\r\n  overflow: hidden scroll;\r\n}\r\n\r\n// SelectOption\r\n\r\n.option {\r\n  @include flex.column;\r\n  width: 100%;\r\n  @include spacing.padding($x: $option-padding-x, $y: $option-padding-y);\r\n  font-size: map.get($value, font-size);\r\n  @include transition.apply(background-color);\r\n  user-select: none;\r\n  cursor: pointer;\r\n\r\n  .light & {\r\n    background-color: $option-light-background-color;\r\n  }\r\n\r\n  .dark & {\r\n    background-color: $option-dark-background-color;\r\n  }\r\n\r\n  &:hover {\r\n    .light & {\r\n      background-color: $option-light-background-color-hover;\r\n    }\r\n\r\n    .dark & {\r\n      background-color: $option-dark-background-color-hover;\r\n    }\r\n  }\r\n\r\n  &.focused {\r\n    .light & {\r\n      background-color: $option-light-background-color-focused;\r\n\r\n      &:hover {\r\n        background-color: $option-light-background-color-focused-hover;\r\n      }\r\n    }\r\n\r\n    .dark & {\r\n      background-color: $option-dark-background-color-focused;\r\n\r\n      &:hover {\r\n        background-color: $option-dark-background-color-focused-hover;\r\n      }\r\n    }\r\n  }\r\n\r\n  &.selected {\r\n    .light & {\r\n      background-color: $option-light-background-color-selected;\r\n\r\n      &:hover {\r\n        background-color: $option-light-background-color-selected-hover;\r\n      }\r\n    }\r\n\r\n    .dark & {\r\n      background-color: $option-dark-background-color-selected;\r\n\r\n      &:hover {\r\n        background-color: $option-dark-background-color-selected-hover;\r\n      }\r\n    } // end .dark &\r\n  } // end &.selected\r\n\r\n  &.disabled {\r\n    opacity: $opacity-disabled;\r\n    pointer-events: none;\r\n  }\r\n}\r\n\r\n.optionRow {\r\n  @include flex.row-between;\r\n  width: 100%;\r\n\r\n  .light & {\r\n    color: $option-light-color;\r\n  }\r\n\r\n  .dark & {\r\n    color: $option-dark-color;\r\n  }\r\n\r\n  .selected & {\r\n    .light & {\r\n      color: $option-light-color-selected;\r\n    }\r\n\r\n    .dark & {\r\n      color: $option-dark-color-selected;\r\n    }\r\n  }\r\n}\r\n\r\n// .optionLabel {\r\n//   flex: 2 0;\r\n// }\r\n\r\n.optionRightLabel {\r\n  // flex: 1;\r\n  @include spacing.margin($left: $option-right-label-spacing);\r\n  font-size: $option-right-label-font-size;\r\n  text-align: right;\r\n\r\n  .light & {\r\n    color: $option-right-label-light-color;\r\n  }\r\n\r\n  .dark & {\r\n    color: $option-right-label-dark-color;\r\n  }\r\n\r\n  .selected & {\r\n    .light & {\r\n      color: inherit;\r\n    }\r\n\r\n    .dark & {\r\n      color: inherit;\r\n    }\r\n  }\r\n}\r\n\r\n.optionSubLabel {\r\n  font-size: $option-sub-label-font-size;\r\n\r\n  .light & {\r\n    color: $option-sub-label-light-color;\r\n  }\r\n\r\n  .dark & {\r\n    color: $option-sub-label-dark-color;\r\n  }\r\n\r\n  // note: .optionSubLabel is not inside .optionRow, so it's not possible\r\n  // to inherit .optionRow's color here (like in .optionRightLabel)\r\n  .selected & {\r\n    .light & {\r\n      color: $option-light-color-selected;\r\n    }\r\n\r\n    .dark & {\r\n      color: $option-dark-color-selected;\r\n    }\r\n  }\r\n}\r\n\r\n.optionItem {\r\n  &:first-child {\r\n    border-radius: $border-radius $border-radius 0 0;\r\n  }\r\n\r\n  &:last-child {\r\n    border-radius: 0 0 $border-radius $border-radius;\r\n  }\r\n}\r\n\r\n// SelectNotice\r\n\r\n.notice {\r\n  @include spacing.padding($x: $notice-padding-x, $y: $notice-padding-y);\r\n  font-size: map.get($value, font-size);\r\n  text-align: center;\r\n  user-select: none;\r\n\r\n  .light & {\r\n    color: $notice-light-color;\r\n  }\r\n\r\n  .dark & {\r\n    color: $notice-dark-color;\r\n  }\r\n}\r\n","///\r\n/// @group flex\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n/// @since 0.1.0\r\n///\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -flex(\r\n  $direction: null,\r\n  $justify: null,\r\n  $align: null,\r\n  $inline: false,\r\n) {\r\n  display: if($inline, inline-flex, flex);\r\n\r\n  @if $direction and $direction != row {\r\n    flex-direction: $direction;\r\n  }\r\n\r\n  @if $justify and $justify != flex-start {\r\n    justify-content: $justify;\r\n  }\r\n\r\n  @if $align and $align != stretch {\r\n    align-items: $align;\r\n  }\r\n}\r\n\r\n// rows\r\n\r\n@mixin row(\r\n  $justify: null,\r\n  $align: null,\r\n  $reverse: false,\r\n  $inline: false,\r\n) {\r\n  @include -flex(\r\n    if($reverse, row-reverse, row),\r\n    $justify,\r\n    $align,\r\n    $inline,\r\n  );\r\n}\r\n\r\n@mixin row-stretch($reverse: false, $inline: false) {\r\n  @include row(stretch, stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-stretch()\r\n///\r\n@mixin stretch($reverse: false, $inline: false) {\r\n  @include row-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-start($align: center, $reverse: false, $inline: false) {\r\n  @include row(flex-start, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-start()\r\n///\r\n@mixin start($align: center, $reverse: false, $inline: false) {\r\n  @include row-start($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-start-stretch($reverse: false, $inline: false) {\r\n  @include row-start(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-start-stretch()\r\n///\r\n@mixin start-stretch($reverse: false, $inline: false) {\r\n  @include row-start-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-center($align: center, $reverse: false, $inline: false) {\r\n  @include row(center, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-center()\r\n///\r\n@mixin center($align: center, $reverse: false, $inline: false) {\r\n  @include row-center($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-center-stretch($reverse: false, $inline: false) {\r\n  @include row-center(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-center-stretch()\r\n///\r\n@mixin center-stretch($reverse: false, $inline: false) {\r\n  @include row-center-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-end($align: center, $reverse: false, $inline: false) {\r\n  @include row(flex-end, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-end()\r\n///\r\n@mixin end($align: center, $reverse: false, $inline: false) {\r\n  @include row-end($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-end-stretch($reverse: false, $inline: false) {\r\n  @include row-end(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-end-stretch()\r\n///\r\n@mixin end-stretch($reverse: false, $inline: false) {\r\n  @include row-end-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-between($align: center, $reverse: false, $inline: false) {\r\n  @include row(space-between, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-between()\r\n///\r\n@mixin between($align: center, $reverse: false, $inline: false) {\r\n  @include row-between($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-between-stretch($reverse: false, $inline: false) {\r\n  @include row-between(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-between-stretch()\r\n///\r\n@mixin between-stretch($reverse: false, $inline: false) {\r\n  @include row-between-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-around($align: center, $reverse: false, $inline: false) {\r\n  @include row(space-around, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-around()\r\n///\r\n@mixin around($align: center, $reverse: false, $inline: false) {\r\n  @include row-around($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-around-stretch($reverse: false, $inline: false) {\r\n  @include row-around(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-around-stretch()\r\n///\r\n@mixin around-stretch($reverse: false, $inline: false) {\r\n  @include row-around-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin row-evenly($align: center, $reverse: false, $inline: false) {\r\n  @include row(space-evenly, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-evenly()\r\n///\r\n@mixin evenly($align: center, $reverse: false, $inline: false) {\r\n  @include row-evenly($align, $reverse, $inline);\r\n}\r\n\r\n@mixin row-evenly-stretch($reverse: false, $inline: false) {\r\n  @include row-evenly(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias row-evenly-stretch()\r\n///\r\n@mixin evenly-stretch($reverse: false, $inline: false) {\r\n  @include row-evenly-stretch($reverse, $inline);\r\n}\r\n\r\n// columns\r\n\r\n@mixin column(\r\n  $justify: null,\r\n  $align: null,\r\n  $reverse: false,\r\n  $inline: false,\r\n) {\r\n  @include -flex(\r\n    if($reverse, column-reverse, column),\r\n    $justify,\r\n    $align,\r\n    $inline,\r\n  );\r\n}\r\n\r\n///\r\n/// @alias column()\r\n///\r\n@mixin col(\r\n  $justify: null,\r\n  $align: null,\r\n  $reverse: false,\r\n  $inline: false,\r\n) {\r\n  @include column($justify, $align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-stretch($reverse: false, $inline: false) {\r\n  @include column(stretch, stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-stretch()\r\n///\r\n@mixin col-stretch($reverse: false, $inline: false) {\r\n  @include column-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-start($align: center, $reverse: false, $inline: false) {\r\n  @include column(flex-start, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-start()\r\n///\r\n@mixin col-start($align: center, $reverse: false, $inline: false) {\r\n  @include column-start($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-start-stretch($reverse: false, $inline: false) {\r\n  @include column-start(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-start-stretch()\r\n///\r\n@mixin col-start-stretch($reverse: false, $inline: false) {\r\n  @include column-start-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-center($align: center, $reverse: false, $inline: false) {\r\n  @include column(center, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-center()\r\n///\r\n@mixin col-center($align: center, $reverse: false, $inline: false) {\r\n  @include column-center($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-center-stretch($reverse: false, $inline: false) {\r\n  @include column-center(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-center-stretch()\r\n///\r\n@mixin col-center-stretch($reverse: false, $inline: false) {\r\n  @include column-center-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-end($align: center, $reverse: false, $inline: false) {\r\n  @include column(flex-end, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-end()\r\n///\r\n@mixin col-end($align: center, $reverse: false, $inline: false) {\r\n  @include column-end($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-end-stretch($reverse: false, $inline: false) {\r\n  @include column-end(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-end-stretch()\r\n///\r\n@mixin col-end-stretch($reverse: false, $inline: false) {\r\n  @include column-end-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-between($align: center, $reverse: false, $inline: false) {\r\n  @include column(space-between, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-between()\r\n///\r\n@mixin col-between($align: center, $reverse: false, $inline: false) {\r\n  @include column-between($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-between-stretch($reverse: false, $inline: false) {\r\n  @include column-between(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-between-stretch()\r\n///\r\n@mixin col-between-stretch($reverse: false, $inline: false) {\r\n  @include column-between-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-around($align: center, $reverse: false, $inline: false) {\r\n  @include column(space-around, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-around()\r\n///\r\n@mixin col-around($align: center, $reverse: false, $inline: false) {\r\n  @include column-around($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-around-stretch($reverse: false, $inline: false) {\r\n  @include column-around(stretch, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-around-stretch()\r\n///\r\n@mixin col-around-stretch($reverse: false, $inline: false) {\r\n  @include column-around-stretch($reverse, $inline);\r\n}\r\n\r\n@mixin column-evenly($align: center, $reverse: false, $inline: false) {\r\n  @include column(space-evenly, $align, $reverse, $inline);\r\n}\r\n\r\n///\r\n/// @alias column-evenly()\r\n///\r\n@mixin col-evenly($align: center, $reverse: false, $inline: false) {\r\n  @include column-evenly($align, $reverse, $inline);\r\n}\r\n\r\n@mixin column-evenly-stretch($reverse: false, $inline: false) {\r\n  @include column-evenly(stretch, $reverse, $inline);\r\n}\r\n","////\r\n/// @group transition\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:list';\r\n@use 'sass:meta';\r\n@use 'config/animations';\r\n\r\n@mixin apply($props...) {\r\n  $transitions: ();\r\n\r\n  @for $i from 1 through list.length($props) {\r\n    $prop: list.nth($props, $i);\r\n\r\n    $name: $prop;\r\n    $duration: animations.$transition-duration;\r\n    $function: animations.$transition-function;\r\n\r\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\r\n      $name: list.nth($prop, 1);\r\n\r\n      @if list.nth($prop, 2) {\r\n        $duration: list.nth($prop, 2);\r\n      }\r\n\r\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\r\n        $function: list.nth($prop, 3);\r\n      }\r\n    }\r\n\r\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\r\n  }\r\n\r\n  @if list.length($transitions) > 0 {\r\n    transition: #{list.zip($transitions)};\r\n  }\r\n}\r\n","////\r\n/// @group spacing\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n/// @since 0.1.0\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n///\r\n/// @alias margin()\r\n///\r\n@mixin m(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include margin(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-axis()\r\n///\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center {\r\n  @include margin($x: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-center()\r\n///\r\n@mixin mx-auto {\r\n  @include margin-center;\r\n}\r\n\r\n@mixin margin-middle {\r\n  @include margin($y: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-middle()\r\n///\r\n@mixin my-auto {\r\n  @include margin-middle;\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n///\r\n/// @alias margin-all()\r\n///\r\n@mixin margin-square($margin) {\r\n  @include margin-all($margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin-all(auto);\r\n}\r\n\r\n///\r\n/// @alias margin-auto()\r\n///\r\n@mixin m-auto {\r\n  @include margin-auto;\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin-all(0);\r\n}\r\n\r\n///\r\n/// @alias margin-none()\r\n///\r\n@mixin m-none {\r\n  @include margin-none;\r\n}\r\n\r\n///\r\n/// @alias m-none()\r\n///\r\n@mixin m-0 {\r\n  @include m-none;\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-xy()\r\n///\r\n@mixin margin-axis($vertical: null, $horizontal: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-x($x: null) {\r\n  @include margin($x: $x);\r\n}\r\n\r\n///\r\n/// @alias margin-x()\r\n///\r\n@mixin mx($x: null) {\r\n  @include margin-x($x: $x);\r\n}\r\n\r\n@mixin mx-none {\r\n  @include mx($x: 0);\r\n}\r\n\r\n///\r\n/// @alias mx-none()\r\n///\r\n@mixin mx-0 {\r\n  @include mx-none;\r\n}\r\n\r\n@mixin margin-y($y: null) {\r\n  @include margin($y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-y()\r\n///\r\n@mixin my($y: null) {\r\n  @include margin-y($y: $y);\r\n}\r\n\r\n@mixin my-none {\r\n  @include my($y: 0);\r\n}\r\n\