p (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n///\r\n/// @alias margin()\r\n///\r\n@mixin m(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include margin(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-axis()\r\n///\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center {\r\n  @include margin($x: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-center()\r\n///\r\n@mixin mx-auto {\r\n  @include margin-center;\r\n}\r\n\r\n@mixin margin-middle {\r\n  @include margin($y: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-middle()\r\n///\r\n@mixin my